```python
import math
from numbers import Real
from typing import Sequence


def mean_absolute_error(
    observed: Sequence[Real], predicted: Sequence[Real]
) -> float:
    if not isinstance(observed, Sequence) or isinstance(observed, (str, bytes)):
        raise TypeError("observed must be a numeric sequence")
    if not isinstance(predicted, Sequence) or isinstance(predicted, (str, bytes)):
        raise TypeError("predicted must be a numeric sequence")
    if len(observed) == 0 or len(observed) != len(predicted):
        raise ValueError("sequences must have equal, nonzero length")

    left: list[float] = []
    right: list[float] = []
    for first, second in zip(observed, predicted):
        if isinstance(first, bool) or not isinstance(first, Real):
            raise TypeError("observed values must be real numbers")
        if isinstance(second, bool) or not isinstance(second, Real):
            raise TypeError("predicted values must be real numbers")
        first_float = float(first)
        second_float = float(second)
        if not math.isfinite(first_float) or not math.isfinite(second_float):
            raise ValueError("values must be finite")
        left.append(first_float)
        right.append(second_float)

    total = sum(abs(first - second) for first, second in zip(left, right))
    return total / sum(abs(value) for value in left)
```

